content:
{
  "patches": [
    {
      "path": "styles.css",
      "oldString": ".class-card p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}",
      "newString": ".class-card .class-art[data-kind="도자기"] {
  background-color: #f4e8d9;
}

.class-card .class-art[data-kind="가죽"] {
  background-color: #e6d5c3;
}

.class-card .class-art[data-kind="나무"] {
  background-color: #d9cbb8;
}

.class-card .class-art::before,
.class-card .class-art::after {
  content: "";
  position: absolute;
  background-color: rgba(45, 42, 38, 0.15);
}

.class-card .class-art[data-kind="도자기"]::before {
  width: 60%;
  height: 40%;
  bottom: 20%;
  left: 20%;
  border-radius: 50% 50% 10% 10%;
}

.class-card .class-art[data-kind="도자기"]::after {
  width: 30%;
  height: 10%;
  bottom: 20%;
  left: 35%;
  border-radius: 50%;
}

.class-card .class-art[data-kind="가죽"]::before {
  width: 50%;
  height: 60%;
  top: 20%;
  left: 25%;
  border-radius: 10px;
}

.class-card .class-art[data-kind="가죽"]::after {
  width: 40%;
  height: 20%;
  top: 30%;
  left: 30%;
  border-radius: 5px;
}

.class-card .class-art[data-kind="나무"]::before {
  width: 70%;
  height: 40%;
  bottom: 20%;
  left: 15%;
  border-radius: 50% / 20%;
}

.class-card .class-art[data-kind="나무"]::after {
  width: 20%;
  height: 60%;
  bottom: 20%;
  left: 40%;
  border-radius: 50%;
}

.class-card .class-price {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-text);
}

.class-card .class-logistics {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.class-card .class-logistics img {
  flex-shrink: 0;
}

.class-card .class-description {
  font-size: 16px;
  line-height: 1.5;
}"
    }
  ]
}
